// DeleteUniqueIndexCache 删除索引存在的缓存
func (p *PlatformGoodRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.PlatformGood) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, p.cache.Key(CachePlatformGoodByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[p.cache.Key(CachePlatformGoodByIDPrefix, item.ID)] = struct{}{}
			KeyMap[p.cache.Key(CachePlatformGoodByNamePrefix, item.Name)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := p.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
